#### P1440 求 m 区间内的最小值
https://www.luogu.com.cn/problem/P1440#ide
同样是模板题，单靠 [[#P1886 【模板】单调队列 / 滑动窗口|P1886 【模板】单调队列 / 滑动窗口]]
```cpp
int main() {
	int n, windowSize;
	cin >> n >> windowSize;

	vector<int> nums(n);
	for(int i = 0; i < n; i++) {
		cin >> nums[i];
	}

	deque<int> dq;
	for(int i = 0; i < n; i++) {
		if(i == 0) {
			cout << 0 << '\n';
		} else {
			cout << nums[dq.front()] << '\n';
		}
		while(!dq.empty() && nums[dq.back()] >= nums[i]) {
			dq.pop_back();
		}
		dq.push_back(i);
		while(!dq.empty() && dq.front() <= i - windowSize) {
			dq.pop_front();
		}
	}

	return 0;
}
```

